update public.units
set cultural_note='Nauryz (наурыз = "new day") is the Kazakh New Year, celebrated 21 March at the spring equinox. Streets fill with цастақан (yurt camps), people share Nauryz көже (a seven-ingredient soup), and elders give бата (blessings). The greeting is «Наурыз құтты болсын!» — "Happy Nauryz!"'
where id='u24';

